commands.command:
set -euo pipefail; test "$(git rev-parse HEAD)" = "0892e16c1d2254399c044f1d35e4420bd4002845"; SDK="${ANDROID_SDK_ROOT:-${ANDROID_HOME:-$HOME/Library/Android/sdk}}"; ADB="$SDK/platform-tools/adb"; SERIAL=$("$ADB" devices | awk 'NR>1 && $2=="device" {print $1; exit}'); test -n "$SERIAL"; SOCKET=$("$ADB" -s "$SERIAL" shell cat /proc/net/unix | sed -n 's/.*@\(webview_devtools_remote_[0-9]*\)$/\1/p' | tail -1 | tr -d '\r'); test -n "$SOCKET"; "$ADB" -s "$SERIAL" forward --remove tcp:9222 >/dev/null 2>&1 || true; "$ADB" -s "$SERIAL" forward tcp:9222 localabstract:"$SOCKET" >/dev/null; node --input-type=module - <<'NODE'
const TARGET='shellyplugsg3-e4b063e3e298';
const EXPECTED='E4:B0:63:E3:E2:9A';
const KEY='lcl.savedBlePlugs.v1';
const targets=await fetch('http://127.0.0.1:9222/json/list').then(r=>r.json());
const target=targets.find(t=>t.type==='page')??targets[0];
if(!target?.webSocketDebuggerUrl) throw new Error('No debuggable WebView target');
const ws=new WebSocket(target.webSocketDebuggerUrl); let nextId=1; const pending=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data); if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
const call=(method,params={})=>new Promise((resolve,reject)=>{const id=nextId++; const timer=setTimeout(()=>{pending.delete(id);reject(new Error('CDP timeout '+method));},15000); pending.set(id,msg=>{clearTimeout(timer);resolve(msg)}); ws.send(JSON.stringify({id,method,params}));});
const evalValue=async(expression)=>{const res=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true}); if(res.result?.exceptionDetails) throw new Error(JSON.stringify(res.result.exceptionDetails)); return res.result?.result?.value;};
const snapshotExpr=`(()=>{const raw=localStorage.getItem(${JSON.stringify(KEY)}); const parsed=raw?JSON.parse(raw):null; const plug=parsed?.plugs?.find(p=>String(p.physicalId).trim().toLowerCase()===${JSON.stringify(TARGET)}); const cards=[...document.querySelectorAll('article.automation-card.plug-card--unconfigured')].map(card=>({text:card.innerText,buttons:[...card.querySelectorAll('button')].map(b=>({text:b.textContent?.trim(),pressed:b.getAttribute('aria-pressed'),disabled:b.disabled})),alerts:[...card.querySelectorAll('[role=alert]')].map(x=>x.textContent?.trim())})); return JSON.stringify({plug,cards});})()`;
let settled=null;
for(let i=0;i<30;i++){
 const snap=JSON.parse(await evalValue(snapshotExpr));
 const card=snap.cards.find(c=>snap.plug&&c.text.includes(snap.plug.name));
 const off=card?.buttons.find(b=>b.text==='OFF');
 if(snap.plug?.bleDeviceId===EXPECTED && String(snap.plug.physicalId).trim().toLowerCase()===TARGET && off?.pressed==='true' && off.disabled===false && card.alerts.length===0){settled={plug:snap.plug,card};break;}
 await new Promise(r=>setTimeout(r,2000));
}
if(!settled) throw new Error('Recovered Plug did not settle to readable OFF state');
console.log('SETTLED='+JSON.stringify(settled));
console.log('VERIFY='+JSON.stringify({physicalId:settled.plug.physicalId,bleDeviceId:settled.plug.bleDeviceId,relay:'OFF',controlsEnabled:true,alerts:[]}));
ws.close();
NODE
printf '%s\n' '--- BLE log evidence ---'; "$ADB" -s "$SERIAL" logcat -d -v brief | grep -Ei 'BluetoothLeScanner|BluetoothGatt|BleClient|scan' | tail -200 || true; printf '%s\n' '--- repository cleanliness ---'; git status --short; git diff --check
